tools.example:
model.component("comp1").multiphysics().create("tpf1", "TwoPhaseFlowLevelSet", 2);
model.component("comp1").multiphysics("tpf1").selection().all();
// GUI: Fluid 1 = Water, Fluid 2 = Air, Surface tension coefficient: Library coefficient Water/Air
// Application Library: CFD_Module/Multiphase_Flow/capillary_filling_ls, rising_bubble_2daxi

model.component("comp1").multiphysics().create("ww1", "WettedWall", 1);
model.component("comp1").multiphysics("ww1").selection().set(new int[]{2, 3});
// GUI: Contact angle = 67[deg]
// Application Library: CFD_Module/Multiphase_Flow/capillary_filling_ls

model.component("comp1").physics().create("ls", "LevelSet", "geom1");
// GUI: Level Set Model 1 > Reinitialization parameter = 0.2[m/s]; Parameter controlling interface thickness = ls.ep_default
// Application Library: CFD_Module/Multiphase_Flow/dam_break_column_ls

model.component("comp1").physics("ls").feature("initfluid2").selection().set(new int[]{2});
// domain 2 starts as Fluid 2, domain 1 as Fluid 1; the shared boundary is the initial interface
model.study().create("std1");
model.study("std1").create("phasei", "PhaseInitialization");
model.study("std1").create("time", "Transient");

model.component("comp1").physics().create("tff", "ThinFilmFlowShell", "geom1");
model.component("comp1").physics().create("pftff", "PhaseFieldThinFilmFlowShell", "geom1");
// then add the Two-Phase Thin-Film Flow, Phase Field coupling under Multiphysics

model.component("comp1").physics("bf").create("mt1", "MassTransfer", 2);
model.component("comp1").physics("bf").feature("mt1").selection().all();
// Two-film theory: dissolved concentration c taken from a Transport of Diluted Species interface (c)
